function validate([n]) {
  if (!Number.isInteger(n) || n < 1 || n > 18) return 'n is a whole number from 1 to 18.';
  return null;
}

reference:
function validStrings(n) {
  const result = [];
  const chars = [];

  const extend = () => {
    if (chars.length === n) {
      result.push(chars.join(''));
      return;
    }
    if (chars.length === 0 || chars[chars.length - 1] === '1') {
      chars.push('0');
      extend();
      chars.pop();
    }
    chars.push('1');
    extend();
    chars.pop();
  };

  extend();
  return result;
}

brute:
function validStrings(n) {
  const valid = [];
  for (let mask = 0; mask < 2 ** n; mask++) {
    const text = mask.toString(2).padStart(n, '0');
    if (!text.includes('00')) valid.push(text);
  }
  return valid;
}

